on conflict (name) do update set difficulty_label=excluded.difficulty_label, description=excluded.description, sort_order=excluded.sort_order, max_cards=excluded.max_cards, is_active=excluded.is_active;

on conflict (legacy_id) do update set level_id=excluded.level_id, phrase=excluded.phrase, translation=excluded.translation, explanation=excluded.explanation, topic=excluded.topic, image_path=excluded.image_path, correct_answer=excluded.correct_answer, options=excluded.options, is_published=excluded.is_published;
