(1,(select id from public.levels where name='Principiante'),'I''m fine.','Estoy bien.','Una respuesta corta y común para decir que estás bien.','Vida real',null,'multiple_choice','fine',array['fine','okay','hello']::text[],true),
(2,(select id from public.levels where name='Principiante'),'No worries!','¡No te preocupes!','Se usa para tranquilizar a alguien después de un error pequeño o una disculpa.','Vida real',null,'multiple_choice','No worries',array['No worries','Good bye','Thank you']::text[],true),
(3,(select id from public.levels where name='Principiante'),'See you later!','¡Nos vemos luego!','Una despedida informal que indica que esperas volver a ver a la persona.','Conversación',null,'multiple_choice','See you later',array['See you later','Good morning','I am hungry']::text[],true),
(4,(select id from public.levels where name='Principiante'),'Thank you so much.','Muchas gracias.','Una forma cálida de agradecer algo importante o amable.','Vida real',null,'multiple_choice','Thank you so much',array['Thank you so much','Excuse me','Good night']::text[],true),
(5,(select id from public.levels where name='Principiante'),'I am hungry.','Tengo hambre.','La expresión básica para decir que necesitas o quieres comer.','Vida real',null,'multiple_choice','I am hungry',array['I am hungry','I am tired','I am late']::text[],true),
(6,(select id from public.levels where name='Principiante'),'Good morning!','¡Buenos días!','Un saludo habitual durante la mañana.','Vida real',null,'multiple_choice','Good morning',array['Good morning','Good evening','See you later']::text[],true),
(7,(select id from public.levels where name='Principiante'),'Excuse me.','Disculpa.','Se utiliza para llamar la atención o pedir paso de forma educada.','Conversación',null,'multiple_choice','Excuse me',array['Excuse me','You are welcome','Never mind']::text[],true),
(8,(select id from public.levels where name='Principiante'),'You are welcome.','De nada.','Una respuesta habitual cuando alguien te da las gracias.','Conversación',null,'multiple_choice','You are welcome',array['You are welcome','I am sorry','Good luck']::text[],true),
(9,(select id from public.levels where name='Principiante'),'Good luck!','¡Buena suerte!','Se dice para desearle éxito a alguien antes de una actividad.','Vida real',null,'multiple_choice','Good luck',array['Good luck','Good idea','Good night']::text[],true),
(10,(select id from public.levels where name='Principiante'),'I am tired.','Estoy cansado.','Sirve para decir que necesitas descansar o tienes poca energía.','Vida real','/legacy-images/b00d58c2e39f93ed2ece83e2b88259c0.jpg','multiple_choice','I am tired',array['I am tired','I am hungry','I am ready']::text[],true),
(11,(select id from public.levels where name='Medio'),'That makes sense.','Tiene sentido.','Una manera natural de decir que entiendes la lógica o explicación de alguien.','Conversación',null,'multiple_choice','That makes sense',array['That makes sense','I disagree','I am lost']::text[],true),
(12,(select id from public.levels where name='Medio'),'Never mind.','No importa.','Se usa para restar importancia a algo o indicar que ya no hace falta hablarlo.','Conversación',null,'multiple_choice','Never mind',array['Never mind','No problem','Come with me']::text[],true),
(13,(select id from public.levels where name='Medio'),'It depends.','Depende.','Una respuesta útil cuando la solución cambia según la situación.','Conversación',null,'multiple_choice','It depends',array['It depends','It is mine','I am sure']::text[],true),
(14,(select id from public.levels where name='Medio'),'I am running late.','Voy retrasado.','Indica que llegarás más tarde de lo previsto.','Vida real',null,'multiple_choice','I am running late',array['I am running late','I am early','I am leaving']::text[],true),
(15,(select id from public.levels where name='Medio'),'Could you repeat that?','¿Podrías repetir eso?','Una forma educada de pedir que alguien diga algo otra vez.','Conversación',null,'multiple_choice','Could you repeat that',array['Could you repeat that','Could you stop','Did you see me']::text[],true),
(16,(select id from public.levels where name='Medio'),'I will get back to you.','Te responderé después.','Se usa cuando necesitas tiempo antes de dar una respuesta.','Trabajo',null,'multiple_choice','I will get back to you',array['I will get back to you','I will meet you','I will call it']::text[],true),
(17,(select id from public.levels where name='Medio'),'That sounds great.','Eso suena genial.','Una respuesta positiva ante una idea o propuesta.','Conversación',null,'multiple_choice','That sounds great',array['That sounds great','That looks difficult','That feels wrong']::text[],true),
(18,(select id from public.levels where name='Medio'),'I am not sure.','No estoy seguro.','Una manera natural de expresar duda sin afirmar que algo es falso.','Matices',null,'multiple_choice','I am not sure',array['I am not sure','I am ready','I am right']::text[],true),
(19,(select id from public.levels where name='Medio'),'Give me a second.','Dame un segundo.','Pide un momento breve antes de continuar.','Vida real',null,'multiple_choice','Give me a second',array['Give me a second','Give me a chance','Give me money']::text[],true),
(20,(select id from public.levels where name='Medio'),'What do you mean?','¿Qué quieres decir?','Se usa para pedir una explicación o aclaración.','Conversación',null,'multiple_choice','What do you mean',array['What do you mean','Where do you live','When do you leave']::text[],true),
(21,(select id from public.levels where name='Avanzado'),'I see your point.','Entiendo tu punto.','Reconoce el argumento de otra persona sin necesariamente estar de acuerdo.','Matices',null,'multiple_choice','I see your point',array['I see your point','I know your name','I found your phone']::text[],true),
(22,(select id from public.levels where name='Avanzado'),'Let me think it over.','Déjame pensarlo.','Indica que necesitas analizar una propuesta antes de responder.','Trabajo',null,'multiple_choice','Let me think it over',array['Let me think it over','Let me write it down','Let me take it back']::text[],true),
(23,(select id from public.levels where name='Avanzado'),'I could not agree more.','No podría estar más de acuerdo.','Expresa un acuerdo total y enfático.','Matices',null,'multiple_choice','I could not agree more',array['I could not agree more','I could not remember','I could not arrive']::text[],true),
(24,(select id from public.levels where name='Avanzado'),'That is beside the point.','Eso no viene al caso.','Señala que un comentario no aborda el asunto principal.','Matices',null,'multiple_choice','That is beside the point',array['That is beside the point','That is behind the door','That is part of town']::text[],true),
(25,(select id from public.levels where name='Avanzado'),'I am tied up right now.','Estoy ocupado ahora mismo.','Forma informal de decir que no puedes atender algo en este momento.','Trabajo',null,'multiple_choice','I am tied up right now',array['I am tied up right now','I am dressed up now','I am backed up now']::text[],true),
(26,(select id from public.levels where name='Avanzado'),'Let us touch base tomorrow.','Hablemos brevemente mañana.','Expresión profesional para proponer una conversación de seguimiento.','Trabajo',null,'multiple_choice','Let us touch base tomorrow',array['Let us touch base tomorrow','Let us start work tomorrow','Let us travel abroad tomorrow']::text[],true),
