(28,(select id from public.levels where name='Avanzado'),'It is not my cup of tea.','No es lo mío.','Expresa que algo no coincide con tus gustos o preferencias.','Matices',null,'multiple_choice','It is not my cup of tea',array['It is not my cup of tea','It is not my glass of water','It is not my kind of day']::text[],true),
(29,(select id from public.levels where name='Avanzado'),'I would rather not.','Preferiría no hacerlo.','Rechaza una propuesta de forma firme pero relativamente cortés.','Matices',null,'multiple_choice','I would rather not',array['I would rather not','I would like to know','I would never leave']::text[],true),
